package com.cpf.starter.integration.fixedlength;import java.nio.charset.Charset;import java.util.*;public record CpfFixedLengthLayout(String id,int recordLength,Charset charset,List<CpfFixedLengthField> fields){public CpfFixedLengthLayout{if(id==null||id.isBlank()||recordLength<1||charset==null)throw new IllegalArgumentException("invalid layout");fields=List.copyOf(fields);boolean[] used=new boolean[recordLength];for(var f:fields){if(f.offset()+f.length()>recordLength)throw new IllegalArgumentException("field exceeds record: "+f.name());for(int i=f.offset();i<f.offset()+f.length();i++){if(used[i])throw new IllegalArgumentException("overlapping field: "+f.name());used[i]=true;}}}}
